_MODEL_DEFAULTS = {
    "summarization": os.getenv("OPENAI_SUMMARY_MODEL", "gpt-4.1-mini"),
    "extraction": os.getenv("OPENAI_EXTRACTION_MODEL", "gpt-4.1-mini"),
